def svg(title, desc, body, vb="0 0 400 220", id_=None):
    i = id_ or re.sub(r"\W+","-",title.lower())[:30]
    return f'<svg viewBox="{vb}" role="img" aria-labelledby="{i}-t {i}-d" xmlns="http://www.w3.org/2000/svg"><title id="{i}-t">{html.escape(title)}</title><desc id="{i}-d">{html.escape(desc)}</desc>{body}</svg>'
import re
T='font-family="system-ui,sans-serif"'
def box(x,y,w,h,label,fill="#e7f2ef",stroke="#176b60",fs=13,tc="#0f4c45"):
    lines=label.split("|"); n=len(lines)
    t="".join(f'<text x="{x+w/2}" y="{y+h/2+fs*0.35+(k-(n-1)/2)*(fs+3)}" text-anchor="middle" font-size="{fs}" fill="{tc}" {T} font-weight="600">{html.escape(l)}</text>' for k,l in enumerate(lines))
    return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="12" fill="{fill}" stroke="{stroke}" stroke-width="2"/>{t}'
def arrow(x1,y1,x2,y2,label="",col="#d9822b",lx=None,ly=None):
    lab=f'<text x="{lx if lx is not None else (x1+x2)/2}" y="{ly if ly is not None else (y1+y2)/2-8}" text-anchor="middle" font-size="12" fill="#4a5a57" {T}>{html.escape(label)}</text>' if label else ""
    return f'<line x1="{x1}" y1="{y1}" x2="{x2}" y2="{y2}" stroke="{col}" stroke-width="3" marker-end="url(#ah)"/>{lab}'
